SELECT (CONCAT(?qid,"|",COALESCE(?name,""),"|",SUBSTR(STR(?dob),1,10),"|",COALESCE(?ig,""),"|",COALESCE(?tt,""),"|",COALESCE(?occL,""),"|",COALESCE(STR(?refUrl),""),"|",COALESCE(STR(?wiki),""),"##") AS ?row WHERE {
VALUES ?occ { wd:Q4610556 wd:Q3357567 wd:Q762121 wd:Q15982795 wd:Q124408963 }
?p wdt:P31 wd:Q5; wdt:P21 wd:Q6581072; wdt:P106 ?occ.
?p p:P569 ?ds. ?ds ps:P569 ?dob. FILTER(YEAR(?dob)>=1985 && YEAR(?dob)<=2008)
OPTIONAL { ?p wdt:P2003 ?ig }
OPTIONAL { ?p wdt:P7085 ?tt }
FILTER(BOUND(?ig)||BOUND(?tt))
FILTER NOT EXISTS { ?p wdt:P106 wd:Q488111 }
FILTER NOT EXISTS { ?p wdt:P106 wd:Q3286043 }
OPTIONAL { ?p rdfs:label ?name. FILTER(LANG(?name)="en") }
OPTIONAL { ?occ rdfs:label ?occL. FILTER(LANG(?occL)="en") }
OPTIONAL { ?ds prov:wasDerivedFrom/pr:P854 ?refUrl }
OPTIONAL { ?wiki schema:about ?p; schema:isPartOf <https://en.wikipedia.org/> }
FILTER(BOUND(?refUrl)||BOUND(?wiki))
BIND(REPLACE(STR(?p),"http://www.wikidata.org/entity/","") AS ?qid)
} ORDER BY ?qid LIMIT 50 OFFSET 500

